class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            seen = [False] * (n + 2)
            cnt = 0
            for j in range(i, n):
                v = nums[j]
                if not seen[v]:
                    if seen[v - 1] and seen[v + 1]:
                        cnt -= 1
                    elif not seen[v - 1] and not seen[v + 1] and j > i:
                        cnt += 1
                    seen[v] = True
                ans += cnt
        return ans

