class Solution {
public:
    int sumImbalanceNumbers(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            vector<bool> seen(n + 2, false);
            int cnt = 0;
            for (int j = i; j < n; j++) {
                int v = nums[j];
                if (!seen[v]) {
                    if (seen[v - 1] && seen[v + 1]) cnt--;
                    else if (!seen[v - 1] && !seen[v + 1] && j > i) cnt++;
                    seen[v] = true;
                }
                ans += cnt;
            }
        }
        return ans;
    }
};

